import{_ as e,o as n,c as l,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Benchmarking- Repeatable & Comparable - Trent Lloyd, Canonical (Ubuntu)","description":"","frontmatter":{"title":"Benchmarking- Repeatable & Comparable - Trent Lloyd, Canonical (Ubuntu)","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph基准测试","存储性能","分布式存储","SSD性能","蓝店性能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Benchmarking_-_Repeatable_Comparable_-_Trent_Lloyd_Canonical_Ubuntu.md","filePath":"posts/2025/Benchmarking_-_Repeatable_Comparable_-_Trent_Lloyd_Canonical_Ubuntu.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Benchmarking_-_Repeatable_Comparable_-_Trent_Lloyd_Canonical_Ubuntu.md"};function r(i,t,p,_,s,g){return n(),l("div",null,[...t[0]||(t[0]=[a("<p>本次会议的主题是存储性能基准测试中的陷阱，由Trent Lloyd在Canonical（Ubuntu）公司主讲。以下是对会议内容的详细总结：</p><ol><li><p><strong>基准测试的目标</strong>：确保基准测试结果的可重复性和可比性。可重复性意味着多次运行同一基准测试应得到一致的结果，可比性则意味着在不同配置或环境下，基准测试结果应能反映出实际的性能变化。</p></li><li><p><strong>硬盘性能的变异性</strong>：HDD的顺序写入性能会随着写入位置的不同而变化，主要由于磁头移动距离的变化；SSD的写入性能在初始阶段较快，随后会下降，主要由于垃圾回收机制和SLC缓存的使用。</p></li><li><p><strong>存储系统中的性能瓶颈</strong>：内存带宽、PCIe带宽和网络带宽都可能是性能瓶颈。例如，SSD的读写速度可能超过内存带宽，导致内存访问受限。</p></li><li><p><strong>Ceph中的性能陷阱</strong>：</p><ul><li><strong>蓝店性能</strong>：小于4KB的写操作会导致额外的读写操作，影响性能。</li><li><strong>稀疏分配</strong>：RBD中的稀疏分配会导致初始写入性能较低，因为需要创建RADOS对象并分配元数据。</li><li><strong>内存缓存和深度清理</strong>：内存缓存和Ceph的深度清理操作可能会影响基准测试结果。</li></ul></li><li><p><strong>基准测试工具的选择</strong>：FIO是首选工具，支持并行测试；HDparm, RADOS bench, dd等工具性能较差，不建议使用。</p></li><li><p><strong>基准测试的建议</strong>：</p><ul><li>预写入或厚分配虚拟磁盘，以避免稀疏分配带来的性能影响。</li><li>使用较大的虚拟磁盘，并尽量填充存储集群的30%-80%。</li><li>长时间测试，确保SSD能够达到其持续性能。</li><li>在更改配置后，确保测试结果能够反映出实际的性能变化。</li></ul></li><li><p><strong>总结</strong>：基准测试需要考虑多个因素，包括硬件性能、存储系统的设计以及测试工具的选择。通过合理的测试方法，可以更准确地评估存储系统的性能。</p></li></ol><p><strong>后续行动计划</strong>：</p><ul><li>调整基准测试方法，确保测试结果的准确性和可重复性。</li><li>了解BlueStore的配置选项，并根据实际需求进行优化。</li></ul><p>[总结内容]</p>",5)])])}const d=e(o,[["render",r]]);export{u as __pageData,d as default};
